ash":"e1bbf9a2a77e23e72a1e8b8e5c503a19","disclosure":{"version":1,"level":"dd_summary","reason":"性能・適用限界・実績・計画・試算の判断情報。未確認・旧値・DD非掲載という理由だけで秘密度を上げない。掲載範囲と提供元の利用条件は別に管理する。","dd":{"title":"知財・ノウハウの利用条件と確認状況","body_md":"### 大学の技術を事業で使う条件\n\n知財一覧の出願・公開公報と、新会社の利用権を区別する。対象特許・菌株・ノウハウ、用途・地域・期間、独占性、委託製造、改良成果、対価、契約終了時の継続利用を協議する。公開公報の存在だけで、登録済み・有効・独占実施権取得済みとは扱わない。\n\n株の改変・選抜の未公開手順は核心ノウハウとして保持し、通常DDでは利用・引継ぎの条件と確認状況を示す。","summary":"出願の存在と、設立予定会社が事業で使える権利を分けて説明する。","check_reason":null,"source_label":"技術台帳の研究者報告・事業化検討記録"},"field_levels":{"title":"public","summary":"public","body_md":"dd_summary","presentation":"dd_summary","source_ref":"dd_summary","source_url":"dd_summary","check_reason":"dd_summary"},"field_reasons":{"title":"案内・用語・一般的な仕組みの説明。固有の設定・手順・顧客情報を含まず、秘密にする具体的な理由がない。","summary":"案内・用語・一般的な仕組みの説明。固有の設定・手順・顧客情報を含まず、秘密にする具体的な理由がない。","body_md":"性能・適用限界・実績・計画・試算の判断情報。未確認・旧値・DD非掲載という理由だけで秘密度を上げない。掲載範囲と提供元の利用条件は別に管理する。","presentation":"性能・適用限界・実績・計画・試算の判断情報。未確認・旧値・DD非掲載という理由だけで秘密度を上げない。掲載範囲と提供元の利用条件は別に管理する。","source_ref":"性能・適用限界・実績・計画・試算の判断情報。未確認・旧値・DD非掲載という理由だけで秘密度を上げない。掲載範囲と提供元の利用条件は別に管理する。","source_url":"性能・適用限界・実績・計画・試算の判断情報。未確認・旧値・DD非掲載という理由だけで秘密度を上げない。掲載範囲と提供元の利用条件は別に管理する。","check_reason":"性能・適用限界・実績・計画・試算の判断情報。未確認・旧値・DD非掲載という理由だけで秘密度を上げない。掲載範囲と提供元の利用条件は別に管理する。"},"reviewed_hash":"b406aa54c32deb352780ef7ae50fbcbe7e74ee9d822bf41226b04ef870135d4e"}}]'::jsonb) AS x(id text,source_hash text,disclosure jsonb)), updated AS (UPDATE public.project_tech_topics r SET disclosure=x.disclosure FROM input x WHERE r.tech_topic_id=x.id AND r.project_id='p21' AND md5((to_jsonb(r)-'created_at'-'updated_at'-'sort_order')::text)=x.source_hash RETURNING r.tech_topic_id) SELECT count(*) INTO changed FROM updated;
